-- Dear Corner — geography and delivery zones
--
-- geo_areas: every Division / District / Area the checkout dropdowns offer
-- (generated by scripts/build-geo-data.py from nuhil/bangladesh-geocode, MIT).
-- shipping_zones + shipping_zone_areas: delivery fee and days per zone.
--   Inside Dhaka  = Dhaka city (both city corporations): ৳80, 2-3 days
--   Outside Dhaka = everything else (default zone):        ৳130, 3-5 days
-- The free-delivery threshold lives in store_settings (৳1,000).

create table public.geo_areas (
  id integer generated always as identity primary key,
  division text not null,
  district text not null,
  area text not null,
  is_dhaka_city boolean not null default false,
  unique (district, area)
);
alter table public.geo_areas enable row level security;
create index geo_areas_division_idx on public.geo_areas (division, district);

create policy "Anyone can read areas"
  on public.geo_areas for select
  using (true);
create policy "Admins can manage areas"
  on public.geo_areas for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

-- Generated by scripts/build-geo-data.py. Do not edit by hand.

create table public.shipping_zones (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (char_length(name) between 1 and 60),
  fee integer not null check (fee >= 0),
  min_days integer not null check (min_days >= 0),
  max_days integer not null check (max_days >= min_days),
  -- The zone used when no zone area matches. Exactly one.
  is_default boolean not null default false,
  is_active boolean not null default true,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.shipping_zones enable row level security;
create unique index shipping_zones_one_default_idx on public.shipping_zones (is_default) where is_default;

create trigger shipping_zones_set_updated_at
  before update on public.shipping_zones
  for each row execute function private.set_updated_at();

-- Which district (and optionally which area of it) belongs to a zone.
-- area null = the whole district.
create table public.shipping_zone_areas (
  id uuid primary key default gen_random_uuid(),
  zone_id uuid not null references public.shipping_zones (id) on delete cascade,
  district text not null,
  area text,
  created_at timestamptz not null default now(),
  unique nulls not distinct (district, area)
);
alter table public.shipping_zone_areas enable row level security;
create index shipping_zone_areas_zone_idx on public.shipping_zone_areas (zone_id);

create policy "Anyone can read delivery zones"
  on public.shipping_zones for select
  using (is_active or (select public.is_admin()));
create policy "Admins can manage delivery zones"
  on public.shipping_zones for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

create policy "Anyone can read delivery zone areas"
  on public.shipping_zone_areas for select
  using (true);
create policy "Admins can manage delivery zone areas"
  on public.shipping_zone_areas for all to authenticated
  using ((select public.is_admin()))
  with check ((select public.is_admin()));

create trigger shipping_zones_activity
  after insert or update or delete on public.shipping_zones
  for each row execute function private.log_row_activity();
create trigger shipping_zone_areas_activity
  after insert or update or delete on public.shipping_zone_areas
  for each row execute function private.log_row_activity();

-- Seed the two zones and the Dhaka city areas.
with zones as (
  returning id, name
)
select z.id, g.district, g.area
from zones z
join public.geo_areas g on g.is_dhaka_city
where z.name = 'Inside Dhaka';

-- The zone for a delivery address: an exact (district, area) match first,
-- then a whole-district match, then the default zone.
create or replace function public.shipping_zone_for(p_district text, p_area text)
returns public.shipping_zones
language sql
stable
security definer
set search_path = ''
as $$
  select z.*
  from public.shipping_zones z
  left join public.shipping_zone_areas a
    on a.zone_id = z.id
   and a.district = p_district
   and (a.area = p_area or a.area is null)
  where z.is_active
    and (a.id is not null or z.is_default)
  order by
    case when a.area is not null then 0 when a.id is not null then 1 else 2 end,
    z.position
  limit 1;
$$;
